using System.Linq;
using RimWorld;
using Verse;
namespace ElementalHearts {
 public sealed class IncidentWorker_CourtHeraldAssault:IncidentWorker {
  protected override bool CanFireNowSub(IncidentParms parms){var map=parms.target as Map;var state=CourtStories.State;return map!=null&&map.IsPlayerHome&&CourtStories.Enabled&&CourtStories.Enemy!=null&&state!=null&&!state.HasOrder(map)&&Find.TickManager.TicksGame-state.LastAssault>=12*60000&&CourtHeralds.Eligible(parms.points,Find.TickManager.TicksGame)&&(!CourtStrongholds.CampaignSeeded||CourtStrongholds.Active().Any(h=>!h.HasMap));}
  protected override bool TryExecuteWorker(IncidentParms parms){if(!CanFireNowSub(parms))return false;int element;CourtStronghold origin;if(!CourtStrongholds.TryCommander(out element,out origin))return false;parms.faction=CourtStories.Enemy;parms.raidStrategy=RaidStrategyDefOf.ImmediateAttack;parms.raidArrivalMode=PawnsArrivalModeDefOf.EdgeWalkIn;parms.points=System.Math.Min(parms.points,10000);parms.customLetterLabel=CourtHeralds.Titles[element]+" assault";parms.customLetterText="A "+CourtHeralds.Titles[element]+" has arrived with a Court escort"+(origin==null?".":" from "+origin.Label+".")+" The commander wields five "+CourtHeralds.Lineages[element]+" techniques. Its ivory mantle, crimson cloak and faceguard distinguish it from the Knights.\n\nDefeating the Court's strongholds prevents them from dispatching further Herald expeditions.";bool result;using(new CourtRaidScope(true,element))result=IncidentDefOf.RaidEnemy.Worker.TryExecute(parms);if(result)CourtStories.State.MarkAssault();return result;}
 }
 public sealed class IncidentWorker_CourtStrongholdIntel:IncidentWorker {
  protected override bool CanFireNowSub(IncidentParms parms){var map=parms.target as Map;return CourtStories.Enabled&&map!=null&&map.IsPlayerHome&&CourtStories.State!=null&&Find.TickManager.TicksGame>=30*60000&&Find.TickManager.TicksGame-CourtStories.State.LastIntel>=12*60000&&CourtStrongholds.Active().Any(h=>!h.intelRevealed);}
  protected override bool TryExecuteWorker(IncidentParms parms){if(!CanFireNowSub(parms))return false;var hold=CourtStrongholds.Active().Where(h=>!h.intelRevealed).RandomElement();hold.intelRevealed=true;CourtStories.State.MarkIntel();Find.LetterStack.ReceiveLetter("Court dossier: "+hold.Label,"Intercepted Court orders identify "+hold.Label+", a fortified seat of the "+CourtHeralds.Titles[hold.Element]+".\n\nSend a prepared caravan and choose Attack on the world map. Expect one evolved Herald, two normal Knights and six Oathlings, defending a walled courtyard and command hall. The treasury holds silver, gold, advanced components and matching elemental serum; an infirmary and stores provide supplies.\n\nThe garrison and treasure are finite. Defeating this stronghold prevents it from dispatching new Herald expeditions. You can retreat and return; surviving defenders retain their identity.",LetterDefOf.NeutralEvent,hold);return true;}
 }
}
